IF @LockResult < 0 THROW 57200, 'main activation application lock is busy', 1;
DECLARE @ExpectedStage TABLE (FileName nvarchar(4000) NOT NULL, PartNo int NOT NULL, DataSize bigint NOT NULL, Digest varbinary(32) NOT NULL, PRIMARY KEY(FileName,PartNo));
