IF EXISTS (SELECT E.FileName,E.PartNo FROM @ExpectedActive E LEFT JOIN dbo.Config T WITH (UPDLOCK,HOLDLOCK) ON T.FileName=E.FileName AND T.PartNo=E.PartNo AND CONVERT(bigint,T.DataSize)=E.DataSize AND HASHBYTES('SHA2_256',T.BinaryData)=E.Digest WHERE T.FileName IS NULL) THROW 57202, 'Config selected snapshot drifted', 1;
IF (SELECT COUNT_BIG(*) FROM dbo.Config WITH (UPDLOCK,HOLDLOCK) WHERE FileName=N'DynamicallyUpdated') <> 1 OR (SELECT COUNT_BIG(*) FROM dbo.Config WITH (UPDLOCK,HOLDLOCK) WHERE FileName=N'DynamicallyUpdated' AND PartNo=0 AND CONVERT(bigint,DataSize)=45 AND HASHBYTES('SHA2_256',BinaryData)=0xB2BF1FCDC585D7CACD0B5416CE70C9285C614347C6E8586DAABA4B40567972ED) <> 1 THROW 57203, 'Config.DynamicallyUpdated drifted', 1;
IF (SELECT COUNT_BIG(*) FROM dbo.Params WITH (UPDLOCK,HOLDLOCK) WHERE FileName=N'DynamicallyUpdated') <> 1 OR (SELECT COUNT_BIG(*) FROM dbo.Params WITH (UPDLOCK,HOLDLOCK) WHERE FileName=N'DynamicallyUpdated' AND PartNo=0 AND CONVERT(bigint,DataSize)=82 AND HASHBYTES('SHA2_256',BinaryData)=0xF05F5EFB4431350C4C029514138680E18C0D4F808745119DDDBFF5D067C9C6B4) <> 1 THROW 57204, 'Params.DynamicallyUpdated drifted', 1;
