INSERT dbo.Config (FileName,Creation,Modified,Attributes,DataSize,BinaryData,PartNo) SELECT N'16b3681c-426d-4d6f-9ffe-588a23974222_dynupdate_96eee589-ca6c-4269-8b14-1ca1ee9b69ed.0',Creation,Modified,Attributes,DataSize,BinaryData,PartNo FROM dbo.ConfigSave WHERE FileName=N'16b3681c-426d-4d6f-9ffe-588a23974222.0' AND PartNo=0;
IF @@ROWCOUNT <> 1 THROW 57212, 'online promotion source drifted', 1;
