INSERT dbo.Config (FileName,Creation,Modified,Attributes,DataSize,BinaryData,PartNo) SELECT N'root',Creation,Modified,Attributes,DataSize,BinaryData,PartNo FROM dbo.ConfigSave WHERE FileName=N'root' AND PartNo=0;
IF @@ROWCOUNT <> 1 THROW 57212, 'online promotion source drifted', 1;
DELETE FROM dbo.Config WHERE FileName=N'version' AND PartNo=0;
INSERT dbo.Config (FileName,Creation,Modified,Attributes,DataSize,BinaryData,PartNo) SELECT N'version',Creation,Modified,Attributes,DataSize,BinaryData,PartNo FROM dbo.ConfigSave WHERE FileName=N'version' AND PartNo=0;
IF @@ROWCOUNT <> 1 THROW 57212, 'online promotion source drifted', 1;
IF EXISTS (SELECT 1 FROM dbo.Config WITH (UPDLOCK,HOLDLOCK) WHERE FileName=N'versions_dynupdate_96eee589-ca6c-4269-8b14-1ca1ee9b69ed' AND PartNo=0) THROW 57211, 'dynamic alias already exists', 1;
INSERT dbo.Config (FileName,Creation,Modified,Attributes,DataSize,BinaryData,PartNo) SELECT N'versions_dynupdate_96eee589-ca6c-4269-8b14-1ca1ee9b69ed',Creation,Modified,Attributes,DataSize,BinaryData,PartNo FROM dbo.ConfigSave WHERE FileName=N'versions' AND PartNo=0;
IF @@ROWCOUNT <> 1 THROW 57212, 'online promotion source drifted', 1;
IF EXISTS (SELECT 1 FROM dbo.Config WHERE FileName=N'DynamicallyUpdated' AND PartNo=0) UPDATE dbo.Config SET Modified=SYSUTCDATETIME(),DataSize=82,BinaryData=0xEFBBBF7B312C322C34383332646432302D306239652D343565332D613365372D3039353532356266396233662C39366565653538392D636136632D343236392D386231342D3163613165653962363965647D WHERE FileName=N'DynamicallyUpdated' AND PartNo=0 ELSE INSERT dbo.Config (FileName,Creation,Modified,Attributes,DataSize,BinaryData,PartNo) VALUES (N'DynamicallyUpdated',SYSUTCDATETIME(),SYSUTCDATETIME(),0,82,0xEFBBBF7B312C322C34383332646432302D306239652D343565332D613365372D3039353532356266396233662C39366565653538392D636136632D343236392D386231342D3163613165653962363965647D,0);
IF @@ROWCOUNT <> 1 THROW 57213, 'Config.DynamicallyUpdated upsert failed', 1;
IF EXISTS (SELECT 1 FROM dbo.Params WHERE FileName=N'DynamicallyUpdated' AND PartNo=0) UPDATE dbo.Params SET Modified=SYSUTCDATETIME(),DataSize=119,BinaryData=0xEFBBBF7B302C332C38343861306135392D383830332D343435662D623839642D3363666165346639386262642C34383332646432302D306239652D343565332D613365372D3039353532356266396233662C39366565653538392D636136632D343236392D386231342D3163613165653962363965647D WHERE FileName=N'DynamicallyUpdated' AND PartNo=0 ELSE INSERT dbo.Params (FileName,Creation,Modified,Attributes,DataSize,BinaryData,PartNo) VALUES (N'DynamicallyUpdated',SYSUTCDATETIME(),SYSUTCDATETIME(),0,119,0xEFBBBF7B302C332C38343861306135392D383830332D343435662D623839642D3363666165346639386262642C34383332646432302D306239652D343565332D613365372D3039353532356266396233662C39366565653538392D636136632D343236392D386231342D3163613165653962363965647D,0);
IF @@ROWCOUNT <> 1 THROW 57214, 'Params.DynamicallyUpdated upsert failed', 1;
DELETE FROM dbo.ConfigSave;
IF @@ROWCOUNT <> 5 THROW 57220, 'ConfigSave cleanup drifted', 1;
DECLARE @ExpectedPublished TABLE (FileName nvarchar(4000) NOT NULL, PartNo int NOT NULL, DataSize bigint NOT NULL, Digest varbinary(32) NOT NULL, PRIMARY KEY(FileName,PartNo));
INSERT @ExpectedPublished VALUES (N'16b3681c-426d-4d6f-9ffe-588a23974222_dynupdate_96eee589-ca6c-4269-8b14-1ca1ee9b69ed',0, 174,0x2CA5A62B3681C5F667980EED1905CF64410D22AF0B7DE02B3DB571B1B02424BE);
