IF EXISTS (SELECT E.FileName,E.PartNo FROM @ExpectedPublished E LEFT JOIN dbo.Config T WITH (UPDLOCK,HOLDLOCK) ON T.FileName=E.FileName AND T.PartNo=E.PartNo AND CONVERT(bigint,T.DataSize)=E.DataSize AND HASHBYTES('SHA2_256',T.BinaryData)=E.Digest WHERE T.FileName IS NULL) THROW 57222, 'Config selected snapshot drifted', 1;
IF (SELECT COUNT_BIG(*) FROM dbo.Config WHERE FileName=N'DynamicallyUpdated' AND PartNo=0 AND CONVERT(bigint,DataSize)=82 AND HASHBYTES('SHA2_256',BinaryData)=0x6CCA7BB82241678CA1AA120C28A06E61CD0A87B7F80EED7C458EA82748C61B2E) <> 1 THROW 57223, 'Config.DynamicallyUpdated postcondition failed', 1;
IF (SELECT COUNT_BIG(*) FROM dbo.Params WHERE FileName=N'DynamicallyUpdated' AND PartNo=0 AND CONVERT(bigint,DataSize)=119 AND HASHBYTES('SHA2_256',BinaryData)=0xD929C5543C4D55151DF336FAFD10E35816D23A98AB463EACF08710F41344FAF7) <> 1 THROW 57224, 'Params.DynamicallyUpdated postcondition failed', 1;
IF EXISTS (SELECT 1 FROM dbo.ConfigSave) THROW 57221, 'ConfigSave postcondition failed', 1;
